// Runnable demo: layered defence — rate limit, lockout, CAPTCHA, MFA, IP blacklist.
package com.bank.bruteforce;

import java.util.logging.*;

public class BruteForceDemo {

    private static final Logger log = Logger.getLogger("BruteForce");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AuthService auth = new AuthService();
        String account = "SAV2001", attackerIp = "203.0.113.7";

        // 1) Brute-force burst: wrong password many times from one IP.
        for (int i = 1; i <= 8; i++) {
            final int n = i;
            try {
                auth.login(account, "wrong-guess-" + i, attackerIp, null, null);
            } catch (SecurityException e) {
                log.warning(() -> "attempt " + n + " blocked: " + e.getMessage());
            }
        }

        // 2) Even the CORRECT password fails without the MFA second factor.
        try { auth.login(account, "correct-password", "198.51.100.2", null, null); }
        catch (SecurityException e) { log.severe("correct password alone rejected: " + e.getMessage()); }

        // 3) Correct password + CAPTCHA + valid MFA code → success.
        auth.login(account, "correct-password", "198.51.100.2", "captcha-solved", "123456");
    }
}

// ─── ratelimit/RateLimiter.java (sliding-window counter per key: account+IP) ───
class RateLimiter {
    private final int max; private final long windowMs;
    private final java.util.Map<String, java.util.Deque<Long>> hits = new java.util.HashMap<>();
    RateLimiter(int max, long windowMs) { this.max = max; this.windowMs = windowMs; }
    synchronized boolean allow(String key) {
        long now = System.currentTimeMillis();
        var dq = hits.computeIfAbsent(key, k -> new java.util.ArrayDeque<>());
        while (!dq.isEmpty() && now - dq.peekFirst() > windowMs) dq.pollFirst();  // drop old
        if (dq.size() >= max) return false;    // over the limit → 429
        dq.addLast(now); return true;
    }
}

// ─── throttle/LoginThrottle.java (failure count → lockout + CAPTCHA) ───
class LoginThrottle {
    private final java.util.Map<String, Integer> failures = new java.util.HashMap<>();
    private final java.util.Map<String, Long> lockedUntil = new java.util.HashMap<>();
    private final int lockThreshold = 5, captchaAfter = 3; private final long lockMs = 900_000;
    boolean isLocked(String account) {
        Long until = lockedUntil.get(account);
        return until != null && System.currentTimeMillis() < until;
    }
    boolean captchaRequired(String account) { return failures.getOrDefault(account, 0) >= captchaAfter; }
    void recordFailure(String account) {
        int f = failures.merge(account, 1, Integer::sum);
        if (f >= lockThreshold) lockedUntil.put(account, System.currentTimeMillis() + lockMs);
    }
    void recordSuccess(String account) { failures.remove(account); lockedUntil.remove(account); }
}

// ─── mfa/MfaVerifier.java (second factor) ───
class MfaVerifier {
    boolean verify(String code) { return "123456".equals(code); }   // real: TOTP / SMS OTP
}

// ─── ip/IpBlacklist.java (dynamic block of abusive sources) ───
class IpBlacklist {
    private final java.util.Set<String> blocked = new java.util.HashSet<>();
    void block(String ip) { blocked.add(ip); }
    boolean isBlocked(String ip) { return blocked.contains(ip); }
}

// ─── auth/AuthService.java (composes all layers) ───
class AuthService {
    private static final Logger log = Logger.getLogger("BruteForce");
    private final RateLimiter rateLimiter = new RateLimiter(5, 60_000);
    private final LoginThrottle throttle = new LoginThrottle();
    private final MfaVerifier mfa = new MfaVerifier();
    private final IpBlacklist blacklist = new IpBlacklist();

    void login(String account, String password, String ip, String captcha, String mfaCode) {
        if (blacklist.isBlocked(ip)) throw new SecurityException("IP blacklisted");
        if (!rateLimiter.allow(account + "|" + ip)) {
            blacklist.block(ip);                              // persistent abuse → blacklist
            throw new SecurityException("429 rate limit exceeded");
        }
        if (throttle.isLocked(account)) throw new SecurityException("account temporarily locked");
        if (throttle.captchaRequired(account) && captcha == null)
            throw new SecurityException("CAPTCHA required");
        if (!"correct-password".equals(password)) {          // generic failure (no username/pwd hint)
            throttle.recordFailure(account);
            log.fine(() -> "monitoring: failed login for " + account + " from " + ip);
            throw new SecurityException("invalid credentials");
        }
        if (!mfa.verify(mfaCode)) throw new SecurityException("MFA required / invalid");
        throttle.recordSuccess(account);
        log.info(() -> "login SUCCESS for " + account + " → issue short-lived token (5 min)");
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
